}

function resolverEstado(estados, faltantes) {
  if (!estados.length) return faltantes ? 'sin_material' : 'sin_resultados';
  if (faltantes) return 'parcial';
  const unicos = [...new Set(estados)];
  if (unicos.length === 1) return unicos[0];
