        || typeof asset.mime !== 'string' || !(asset.formato === 'foto' ? /^image\// : /^video\//).test(asset.mime)
        || typeof asset.sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(asset.sha256)
        || !Number.isSafeInteger(asset.bytes) || asset.bytes <= 0)) {
