    if (matches.length) {
      const firmas = new Set(matches.map(r => JSON.stringify([r.estado, r.chatwoot_message_id ?? r.message_id ?? null])));
      const primero = matches[0];
      const msg = primero.chatwoot_message_id ?? primero.message_id ?? null;
