WITH released AS (
  DELETE FROM public.f7_multimedia_locks
  WHERE account_id=$1::bigint AND conversation_id=$2::bigint AND owner=$3::text
  RETURNING 1
)
SELECT EXISTS(SELECT 1 FROM released) AS released;

